from pathlib import Path
import json,hashlib,subprocess
r=Path.cwd();o=r/'target/wp08-verify4';before=json.loads((o/'before-files.json').read_text(encoding='utf-8-sig'));files=subprocess.check_output(['git','ls-files','-z']).decode().split('\0')[:-1];now=[{'path':p,'sha256':hashlib.sha256((r/p).read_bytes()).hexdigest().upper()}for p in files];head=subprocess.check_output(['git','rev-parse','HEAD']).decode().strip();index=subprocess.check_output(['git','ls-files','-s']).decode();status=subprocess.check_output(['git','status','--porcelain=v1']).decode();diff=subprocess.check_output(['git','diff','--binary']).decode();j={'head':head,'head_equal':head==(o/'before-head.txt').read_text(encoding='utf-8-sig').strip(),'tracked_count':len(files),'sha_equal':now==before,'list_equal':[x['path']for x in before]==files,'index_equal':index.splitlines()==(o/'before-index.txt').read_text(encoding='utf-8-sig').splitlines(),'status':status,'diff':diff};(o/'after-files.json').write_text(json.dumps(now,indent=2),encoding='utf-8');(o/'invariance-final.json').write_text(json.dumps(j,indent=2),encoding='utf-8');print(json.dumps(j));raise SystemExit(0 if all(j[k]for k in ['head_equal','sha_equal','list_equal','index_equal'])and not status and not diff else 1)
